pub fn to_uppercase(str1: &Vec<char>) -> Vec<char> {
    str1
        .iter()
        .map(|&c| {
            if c.is_ascii_lowercase() {
                // Convert 'a'..='z' to 'A'..='Z'
                ((c as u8 - b'a' + b'A') as char)
            } else {
                c
            }
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::to_uppercase;

    #[test]
    fn test_empty() {
        let v: Vec<char> = vec![];
        let res = to_uppercase(&v);
        assert!(res.is_empty());
    }

    #[test]
    fn test_all_lowercase() {
        let v: Vec<char> = "abcdefghijklmnopqrstuvwxyz".chars().collect();
        let res = to_uppercase(&v);
        let expected: Vec<char> = "ABCDEFGHIJKLMNOPQRSTUVWXYZ".chars().collect();
        assert_eq!(res, expected);
    }

    #[test]
    fn test_mixed_chars() {
        let v: Vec<char> = "Hello, 世界! 123 aBcZ?".chars().collect();
        let res = to_uppercase(&v);
        let expected: Vec<char> = "HEllo, 世界! 123 ABCZ?".chars().collect();
        assert_eq!(res, expected);
    }

    #[test]
    fn test_non_ascii() {
        let v: Vec<char> = "ñáçø∂".chars().collect();
        let res = to_uppercase(&v);
        // Non-ASCII letters should remain unchanged
        let expected: Vec<char> = "ñáçø∂".chars().collect();
        assert_eq!(res, expected);
    }
}